// Generated by scripts/build_worker.py. Edit server/, then rebuild.
// Shared browser/server rendering. No private notes, customer names or payment data.
function briefEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function briefLink(value){try{const url=new URL(value);return url.protocol==='https:'&&(/(^|\.)gov$/.test(url.hostname)||['harfordcountymd.bonfirehub.com','www.carolinemd.org','carolinemd.org'].includes(url.hostname))?url.href:'#';}catch{return '#';}}
function briefMatches(signals,profile,at=Date.now()){
 return signals.filter(s=>s.status==='open-solicitation'&&s.verification==='verified'&&Date.parse(s.deadline)>at&&Number.isFinite(Date.parse(s.verifiedAt))&&Date.parse(s.verifiedAt)<=at+300000&&at-Date.parse(s.verifiedAt)<172800000&&(!profile.regions.length||profile.regions.includes(s.jurisdiction))&&(!profile.services.length||profile.services.includes(s.category))).sort((a,b)=>Date.parse(a.deadline)-Date.parse(b.deadline));
}
function briefDate(value){const date=new Date(value);return Number.isNaN(date.valueOf())?'Not published':date.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'});}
function renderBriefing({signals,datasetAt,profileLabel='Your selected services and locations',workspaceUrl='',unsubscribeUrl='',preview=false,at=Date.now()}){
 const e=briefEscape;const list=signals.slice(0,50);const soon=list.filter(s=>Date.parse(s.deadline)-at<=7*86400000).length;
 const cards=list.map(s=>`<tr><td style="padding:20px;border-bottom:1px solid #dce3dd"><div style="font-size:11px;letter-spacing:1px;color:#556d65">${e(s.category)} · ${e(s.jurisdiction)}</div><h2 style="font-size:19px;margin:8px 0;color:#173e34">${e(s.title)}</h2><p style="margin:6px 0">${e(s.agency)}</p><p style="margin:6px 0"><strong>Deadline:</strong> ${e(briefDate(s.deadline))}</p>${s.prebidMeeting?`<p style="margin:6px 0"><strong>Pre-bid meeting:</strong> ${e(s.prebidMeeting)}. Check whether attendance is mandatory.</p>`:''}<p style="margin:6px 0">${e(s.summary||'Review the official scope and procurement documents.')}</p>${s.amendmentNotes?.length?`<p><strong>Amendment notes:</strong> ${e(s.amendmentNotes.join(" "))}</p>`:""}${s.requirementNotes?.length?`<p><strong>Requirements stated by source:</strong> ${e(s.requirementNotes.join(" "))}</p>`:""}${s.statusNote?`<p style="font-size:12px;color:#52675e">${e(s.statusNote)}</p>`:''}<p style="font-size:12px;color:#52675e">Source checked ${e(briefDate(s.verifiedAt))}</p><a href="${e(briefLink(s.sourceUrl))}" style="color:#17644c;font-weight:bold">View official evidence ↗</a>${s.procurementUrl?` · <a href="${e(briefLink(s.procurementUrl))}" style="color:#17644c">County-linked bid portal ↗</a>`:''}</td></tr>`).join('');
 // Only same-origin HTTPS application URLs; user-supplied HTML/URLs never pass through.
 function appLink(value){try{const u=new URL(value);return u.protocol==='https:'&&/^[a-z0-9-]+\.cleanupsignal\.pages\.dev$|^cleanupsignal\.pages\.dev$/.test(u.hostname)?e(u.href):'';}catch{return '';}}
 const workspace=appLink(workspaceUrl),unsubscribe=appLink(unsubscribeUrl);
 const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CleanupSignal bid briefing</title></head><body style="margin:0;padding:20px;background:#f2f5f1;font:15px/1.55 Arial,sans-serif;color:#263d34"><table role="presentation" style="width:100%;max-width:740px;margin:auto;border-collapse:collapse;background:#fff"><tr><td style="padding:24px;background:#163d33;color:white;font-size:25px;font-weight:bold">Cleanup<span style="color:#d8e9ae">Signal</span><div style="font-size:11px;font-weight:normal;letter-spacing:2px">MATCHED BID BRIEFING</div></td></tr><tr><td style="padding:24px"><h1 style="font-size:28px;margin:0 0 8px">Your next opportunities, in one place.</h1><p>${e(profileLabel)}</p><p><strong>${list.length} matching open ${list.length===1?'bid':'bids'}</strong> · ${soon} deadlines within 7 days</p><p style="font-size:12px;color:#52675e">Dataset: ${e(briefDate(datasetAt))}${preview?' · Preview generated from the current public dataset; no email has been sent.':''}</p>${list.length?'':'<p>No verified open bids match these preferences right now. This does not mean there are no opportunities in the region. We do not substitute grants or expired notices for actionable bids.</p>'}</td></tr>${cards}<tr><td style="padding:24px;font-size:12px;color:#52675e">Official documents control scope, eligibility, mandatory meetings and amendments. Coverage is incomplete. Funding announcements are not included as open bids.${workspace?`<p><a href="${workspace}">Open company workspace</a></p>`:''}${unsubscribe?`<p><a href="${unsubscribe}">Unsubscribe from bid alerts</a></p>`:''}${preview?'<p>Delivery is awaiting a verified sender. This preview is not a subscription or delivery confirmation.</p>':''}</td></tr></table></body></html>`;
 const text=['CleanupSignal — matched bid briefing',profileLabel,'Dataset: '+briefDate(datasetAt),`${list.length} matching open bids; ${soon} deadlines within 7 days`,'',...list.flatMap(s=>[s.title,s.agency,s.jurisdiction+' / '+s.category,'Deadline: '+briefDate(s.deadline),...(s.prebidMeeting?['Pre-bid meeting: '+s.prebidMeeting]:[]),s.summary,...(s.amendmentNotes||[]),...(s.requirementNotes||[]),s.statusNote||'',briefLink(s.sourceUrl),...(s.procurementUrl?[briefLink(s.procurementUrl)]:[]),'']),'Official documents control scope, eligibility, meetings and amendments.',...(workspace?['Company workspace: '+workspaceUrl]:[]),...(unsubscribe?['Unsubscribe: '+unsubscribeUrl]:[]),...(preview?['Preview only. No email has been sent.']:[])].join('\n');
 return {html,text,count:list.length,soon};
}

// security.js
class HttpError extends Error {constructor(status,message){super(message);this.status=status;}}
function requireValue(ok,status,message){if(!ok)throw new HttpError(status,message);}
function json(data,status=200,headers={}){return Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...headers}});}
async function readText(request,limit=32768){
 requireValue(Number(request.headers.get('content-length')||0)<=limit,413,'Request too large.');
 const reader=request.body?.getReader();if(!reader)return '';let size=0;const chunks=[];
 while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>limit){await reader.cancel();throw new HttpError(413,'Request too large.');}chunks.push(value);}
 const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}return new TextDecoder().decode(bytes);
}
async function bodyJson(request){try{const data=JSON.parse(await readText(request));requireValue(data&&typeof data==='object'&&!Array.isArray(data),400,'JSON object required.');return data;}catch(e){if(e instanceof HttpError)throw e;throw new HttpError(400,'Invalid JSON.');}}
function checkOrigin(request){requireValue(request.headers.get('origin')===new URL(request.url).origin,403,'Request origin rejected.');requireValue(request.headers.get('content-type')?.startsWith('application/json'),415,'JSON required.');}
async function hash(value){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))].map(b=>b.toString(16).padStart(2,'0')).join('');}
function randomToken(){return [...crypto.getRandomValues(new Uint8Array(32))].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function constantEqual(a,b){if(typeof a!=='string'||typeof b!=='string')return false;const key=await crypto.subtle.importKey('raw',new TextEncoder().encode('CleanupSignal constant length comparison'),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);return crypto.subtle.verify('HMAC',key,await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(a)),new TextEncoder().encode(b));}
async function verifyStripe(raw,header,secret,now=Math.floor(Date.now()/1000)){
 const parts=(header||'').split(',');const t=parts.find(s=>s.startsWith('t='))?.slice(2);
 if(!secret||!/^\d+$/.test(t||'')||Math.abs(now-Number(t))>300)return false;
 const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);
 for(const part of parts.filter(s=>/^v1=[a-f0-9]{64}$/i.test(s))){const bytes=Uint8Array.from(part.slice(3).match(/../g),s=>parseInt(s,16));if(await crypto.subtle.verify('HMAC',key,bytes,new TextEncoder().encode(t+'.'+raw)))return true;}
 return false;
}
function cookie(request,name){return request.headers.get('cookie')?.split(';').map(s=>s.trim()).find(s=>s.startsWith(name+'='))?.slice(name.length+1)||'';}
function setSession(response,session){for(const [name,value,maxAge] of [['cs_access',session?.access_token||'',session?3600:0],['cs_refresh',session?.refresh_token||'',session?2592000:0]])response.headers.append('Set-Cookie',`${name}=${value}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${maxAge}`);return response;}
const plans={free:{seats:1},starter:{seats:1,monthly:19,yearly:190},team:{seats:3,monthly:29,yearly:290},business:{seats:8,monthly:49,yearly:490}};
function entitled(company,now=Math.floor(Date.now()/1000)){return ['active','trialing'].includes(company.subscription_status)&&company.period_end>now&&company.plan in plans&&company.plan!=='free';}
function seats(company){return entitled(company)?plans[company.plan].seats:1;}

// public-data.js
function validPublicData(data){return data&&Array.isArray(data.signals)&&Array.isArray(data.sources)&&Number.isFinite(Date.parse(data.generatedAt))&&Date.parse(data.generatedAt)<=Date.now()+300000;}
async function latestDataset(request,env){
 const candidates=[],checks=[];
 try{const response=await env.ASSETS.fetch(new Request(new URL('/data/signals.json',request.url)));if(response.ok){const data=JSON.parse(await readText(response,2000000));if(validPublicData(data))candidates.push({data,source:'deployed-fallback'});}}catch{}
 const bucket=Math.floor(Date.now()/300000);
 const sources=[['github-raw','https://raw.githubusercontent.com/tzj410/CleanupSignal/main/public/data/signals.json?refresh='+bucket],['github-api','https://api.github.com/repos/tzj410/CleanupSignal/contents/public/data/signals.json?ref=main']];
 for(const [source,url] of sources){
  try{
   const response=await fetch(url,{signal:AbortSignal.timeout(3500),headers:{'Cache-Control':'no-cache','User-Agent':'CleanupSignal public data reader','Accept':'application/vnd.github.raw+json'},cf:{cacheTtl:60,cacheEverything:true}});
   if(!response.ok){checks.push({source,status:response.status});await response.body?.cancel();continue;}
   const data=JSON.parse(await readText(response,2000000));
   if(validPublicData(data)){candidates.push({data,source});checks.push({source,status:'valid'});break;}
   checks.push({source,status:'invalid-dataset'});
  }catch{checks.push({source,status:'unavailable'});}
 }
 requireValue(candidates.length,503,'Public bid data is temporarily unavailable.');
 const selected=candidates.sort((a,b)=>Date.parse(b.data.generatedAt)-Date.parse(a.data.generatedAt))[0];
 // Public provenance lets operators distinguish a fresh publication from an upstream fallback.
 return {...selected.data,publication:{source:selected.source,checkedAt:new Date().toISOString(),checks}};
}
async function publicSignals(request,env){return json(await latestDataset(request,env),200,{'Cache-Control':'public, max-age=30, s-maxage=60'});}

// auth.js
function authReady(env){return Boolean(env.SUPABASE_URL&&env.SUPABASE_PUBLISHABLE_KEY);}
async function authCall(env,path,data,token,method='POST'){
 requireValue(authReady(env),503,'Company sign-in is awaiting authentication setup. The public bid center remains available.');
 const r=await fetch(env.SUPABASE_URL+'/auth/v1/'+path,{method,headers:{apikey:env.SUPABASE_PUBLISHABLE_KEY,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(15000)});
 if(!r.ok){await r.body?.cancel();throw new HttpError(r.status===429?429:401,r.status===429?'Too many attempts. Please wait before retrying.':'Sign-in could not be completed. Check your email or request a new link.');}
 return r.status===204?{}:r.json();
}
async function userFor(request,env){const token=cookie(request,'cs_access');requireValue(token,401,'Please sign in.');const u=await authCall(env,'user',null,token,'GET');requireValue(u.id&&u.email&&u.email_confirmed_at&&!u.is_anonymous,403,'Verify your email before continuing.');return u;}
async function rateLimit(request,env,scope,max=15){
 const key=await hash(scope+':'+(request.headers.get('CF-Connecting-IP')||'local'));const window=Math.floor(Date.now()/60000);
 const row=await env.DB.prepare('INSERT INTO rate_limits(key,window,count) VALUES(?,?,1) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN window=excluded.window THEN count+1 ELSE 1 END, window=excluded.window RETURNING count').bind(key,window).first();
 requireValue(row.count<=max,429,'Too many requests. Please try again shortly.');
}
async function authRoute(request,env,path){
 const data=await bodyJson(request);
 if(path==='logout'){const token=cookie(request,'cs_access');if(token)try{await authCall(env,'logout',null,token);}catch{}return setSession(json({ok:true}),null);}
 await rateLimit(request,env,'auth');
 if(path==='otp'){
  requireValue(typeof data.email==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)&&data.email.length<255,400,'Enter a valid business email.');
  await authCall(env,'otp?redirect_to='+encodeURIComponent(new URL('/account.html',request.url).href),{email:data.email.toLowerCase().trim(),create_user:true});
  return json({ok:true,message:'Check your email for a sign-in link or code. This also verifies your email. Use the same method to recover access.'});
 }
 if(path==='verify'){requireValue(typeof data.email==='string'&&typeof data.token==='string'&&/^\d{6,10}$/.test(data.token),400,'Enter the code from your email.');const s=await authCall(env,'verify',{email:data.email,token:data.token,type:'email'});return setSession(json({ok:true}),s);}
 if(path==='session'){requireValue(typeof data.access_token==='string'&&data.access_token.length<8192&&/^[A-Za-z0-9._~-]+$/.test(data.access_token)&&typeof data.refresh_token==='string'&&data.refresh_token.length<4096&&/^[A-Za-z0-9._~-]+$/.test(data.refresh_token),400,'Invalid session.');const u=await authCall(env,'user',null,data.access_token,'GET');requireValue(u.email_confirmed_at&&!u.is_anonymous,403,'Verify your email.');return setSession(json({ok:true}),data);}
 if(path==='refresh'){const token=cookie(request,'cs_refresh');requireValue(token,401,'Please sign in again.');const s=await authCall(env,'token?grant_type=refresh_token',{refresh_token:token});return setSession(json({ok:true}),s);}
 throw new HttpError(404,'Unknown authentication action.');
}

// workspace.js
const regionCodes=['MD','VA','DC'];const serviceCodes=['Assessment','Cleanup','Multipurpose','Abatement','Demolition','Water','Waste','Testing','Monitoring','PFAS','Hygiene','GIS','Federal contracting'];
function listSelection(value,allowed){requireValue(Array.isArray(value)&&value.length<=allowed.length&&value.every(v=>allowed.includes(v)),400,'Invalid project preferences.');return [...new Set(value)];}
async function workspaceFor(request,env,ownerOnly=false){
 const user=await userFor(request,env);
 const company=await env.DB.prepare('SELECT c.*,m.role FROM companies c JOIN members m ON m.company_id=c.id WHERE m.user_id=?').bind(user.id).first();
 requireValue(company,404,'Create a company workspace or accept your invitation first.');
 requireValue(!ownerOnly||company.owner_id===user.id,403,'Only the company owner can manage this setting.');
 // On downgrade, retain data but suspend excess members. Owner always retains access.
 if(company.owner_id!==user.id){const ranked=await env.DB.prepare('SELECT user_id FROM members WHERE company_id=? ORDER BY CASE role WHEN \'owner\' THEN 0 ELSE 1 END,created_at,user_id LIMIT ?').bind(company.id,seats(company)).all();requireValue(ranked.results.some(m=>m.user_id===user.id),403,'Your company has exceeded its plan seat limit. Ask the owner to manage access.');}
 return {user,company};
}
async function workspaceRoute(request,env,path){
 const user=await userFor(request,env);if(request.method!=='GET')await rateLimit(request,env,'workspace',60);
 if(path==='/api/workspace'&&request.method==='POST'){
  const data=await bodyJson(request);requireValue(typeof data.name==='string'&&data.name.trim().length>=2&&data.name.length<=160,400,'Company name must be 2–160 characters.');
  const existing=await env.DB.prepare('SELECT company_id FROM members WHERE user_id=?').bind(user.id).first();requireValue(!existing,409,'You already belong to a company.');const id=crypto.randomUUID();
  await env.DB.batch([env.DB.prepare('INSERT INTO companies(id,name,owner_id) VALUES(?,?,?)').bind(id,data.name.trim(),user.id),env.DB.prepare("INSERT INTO members(user_id,company_id,email,role) VALUES(?,?,?,'owner')").bind(user.id,id,user.email.toLowerCase())]);
  return json({ok:true},201);
 }
 if(path==='/api/invitations/accept'&&request.method==='POST'){
  const data=await bodyJson(request);requireValue(typeof data.token==='string'&&/^[a-f0-9]{64}$/.test(data.token),400,'Invalid invitation.');
  const tokenHash=await hash(data.token);const invite=await env.DB.prepare('SELECT * FROM invitations WHERE token_hash=? AND email=? AND expires_at>unixepoch()').bind(tokenHash,user.email.toLowerCase()).first();requireValue(invite,404,'Invitation expired or belongs to a different email.');
  // Conditional insert and delete share one transaction. Trigger rechecks seats atomically.
  const result=await env.DB.batch([env.DB.prepare("INSERT INTO members(user_id,company_id,email,role) SELECT ?,company_id,email,'member' FROM invitations WHERE token_hash=? AND email=? AND expires_at>unixepoch()").bind(user.id,tokenHash,user.email.toLowerCase()),env.DB.prepare('DELETE FROM invitations WHERE token_hash=?').bind(tokenHash)]);
  requireValue(result[0].meta.changes===1,409,'Invitation already accepted.');return json({ok:true});
 }
 const {company}=await workspaceFor(request,env,['/api/invitations','/api/members'].includes(path));
 if(path==='/api/workspace'&&request.method==='GET'){
  const [members,prefs,watchlist,alerts,invitations]=await Promise.all([
   env.DB.prepare('SELECT user_id,email,role FROM members WHERE company_id=? ORDER BY created_at,user_id').bind(company.id).all(),
   env.DB.prepare('SELECT regions,services FROM preferences WHERE company_id=?').bind(company.id).first(),
   env.DB.prepare('SELECT signal_id,note,reminder_date FROM watchlist WHERE company_id=? ORDER BY created_at DESC LIMIT 500').bind(company.id).all(),
   env.DB.prepare('SELECT frequency,deadlines FROM alert_settings WHERE user_id=?').bind(user.id).first(),
   env.DB.prepare('SELECT email,expires_at FROM invitations WHERE company_id=? AND expires_at>unixepoch()').bind(company.id).all()]);
  return json({user:{id:user.id,email:user.email},company:{id:company.id,name:company.name,plan:company.plan,status:company.subscription_status,paid:entitled(company),seats:seats(company),role:company.role,periodEnd:company.period_end},members:members.results,preferences:prefs?{regions:JSON.parse(prefs.regions),services:JSON.parse(prefs.services)}:{regions:[],services:[]},watchlist:watchlist.results,alerts:alerts||{frequency:'off',deadlines:0},invitations:company.role==='owner'?invitations.results:[]});
 }
 const data=await bodyJson(request);
 if(path==='/api/preferences'&&request.method==='PUT'){
  const regions=listSelection(data.regions,regionCodes),services=listSelection(data.services,serviceCodes);
  await env.DB.prepare('INSERT INTO preferences(company_id,regions,services) VALUES(?,?,?) ON CONFLICT(company_id) DO UPDATE SET regions=excluded.regions,services=excluded.services,updated_at=unixepoch()').bind(company.id,JSON.stringify(regions),JSON.stringify(services)).run();return json({ok:true});
 }
 if(path==='/api/watchlist'&&['PUT','DELETE'].includes(request.method)){
  requireValue(typeof data.signalId==='string'&&/^[a-zA-Z0-9_-]{1,160}$/.test(data.signalId),400,'Invalid project ID.');
  if(request.method==='DELETE')await env.DB.prepare('DELETE FROM watchlist WHERE company_id=? AND signal_id=?').bind(company.id,data.signalId).run();
  else{requireValue(typeof(data.note??'')==='string'&&(data.note||'').length<=4000,400,'Note is too long.');requireValue(!data.reminderDate||/^\d{4}-\d{2}-\d{2}$/.test(data.reminderDate),400,'Invalid reminder date.');
   const count=await env.DB.prepare('SELECT count(*) AS n FROM watchlist WHERE company_id=?').bind(company.id).first();requireValue(count.n<500||await env.DB.prepare('SELECT 1 FROM watchlist WHERE company_id=? AND signal_id=?').bind(company.id,data.signalId).first(),409,'Watchlist limit is 500 projects.');
   await env.DB.prepare('INSERT INTO watchlist(company_id,signal_id,note,reminder_date) VALUES(?,?,?,?) ON CONFLICT(company_id,signal_id) DO UPDATE SET note=CASE WHEN ? THEN excluded.note ELSE watchlist.note END,reminder_date=CASE WHEN ? THEN excluded.reminder_date ELSE watchlist.reminder_date END').bind(company.id,data.signalId,data.note||'',data.reminderDate||null,Number(Object.hasOwn(data,'note')),Number(Object.hasOwn(data,'reminderDate'))).run();}
  return json({ok:true});
 }
 if(path==='/api/invitations'&&request.method==='POST'){
  requireValue(entitled(company),402,'A paid company plan is required for team invitations.');requireValue(typeof data.email==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)&&data.email.length<=254,400,'Enter a valid email.');
  await env.DB.prepare('DELETE FROM invitations WHERE company_id=? AND expires_at<=unixepoch()').bind(company.id).run();const token=randomToken();
  await env.DB.prepare('INSERT INTO invitations(token_hash,company_id,email,expires_at) VALUES(?,?,?,unixepoch()+604800)').bind(await hash(token),company.id,data.email.toLowerCase().trim()).run();
  return json({ok:true,invitationUrl:new URL('/account.html?invite='+token,request.url).href,message:'Share this one-use invitation privately with your colleague. It expires in seven days and requires that email to sign in.'},201);
 }
 if(path==='/api/invitations'&&request.method==='DELETE'){requireValue(typeof data.email==='string',400,'Email required.');await env.DB.prepare('DELETE FROM invitations WHERE company_id=? AND email=?').bind(company.id,data.email).run();return json({ok:true});}
 if(path==='/api/members'&&request.method==='DELETE'){
  requireValue(typeof data.userId==='string'&&data.userId!==company.owner_id,400,'The owner cannot be removed.');await env.DB.prepare('DELETE FROM members WHERE company_id=? AND user_id=?').bind(company.id,data.userId).run();return json({ok:true});
 }
 if(path==='/api/alerts'&&request.method==='PUT'){
  requireValue(['off','daily','weekly'].includes(data.frequency)&&typeof data.deadlines==='boolean',400,'Invalid alert settings.');requireValue(data.frequency==='off'&&!data.deadlines||entitled(company),402,'Subscribe before enabling automated alerts.');
  // A per-user signed-in opt-in is required. Owner cannot opt colleagues in.
  await env.DB.prepare('INSERT INTO alert_settings(user_id,frequency,deadlines) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET frequency=excluded.frequency,deadlines=excluded.deadlines,updated_at=unixepoch()').bind(user.id,data.frequency,Number(data.deadlines)).run();return json({ok:true});
 }
 return json({error:'Unknown workspace action.'},404);
}

// billing.js
function priceMap(env){try{return JSON.parse(env.STRIPE_PRICES||'{}');}catch{return {};}}
function billingReady(env){const p=priceMap(env);return env.BILLING_ENABLED==='true'&&Boolean(env.STRIPE_SECRET_KEY&&env.STRIPE_WEBHOOK_SECRET)&&['starter','team','business'].every(t=>['monthly','yearly'].every(b=>/^price_/.test(p[t+'_'+b]||'')));}
async function stripe(env,path,params=null,key=null){const r=await fetch('https://api.stripe.com/v1/'+path,{method:params?'POST':'GET',headers:{Authorization:'Bearer '+env.STRIPE_SECRET_KEY,'Stripe-Version':'2025-06-30.basil',...(params?{'Content-Type':'application/x-www-form-urlencoded'}:{}),...(key?{'Idempotency-Key':key}:{})},...(params?{body:new URLSearchParams(params)}:{}),signal:AbortSignal.timeout(15000)});if(!r.ok){await r.body?.cancel();throw new Error('Billing provider request failed.');}return r.json();}
async function billingRoute(request,env,path){
 requireValue(billingReady(env),503,'Subscriptions are not open yet. No payment has been taken.');
 const {user,company}=await workspaceFor(request,env,true);await rateLimit(request,env,'billing',10);const data=await bodyJson(request);const origin=env.APP_ORIGIN||new URL(request.url).origin;
 if(path==='/api/billing/portal'){requireValue(company.stripe_customer,409,'There is no billing account yet.');const session=await stripe(env,'billing_portal/sessions',{customer:company.stripe_customer,return_url:origin+'/account.html'});return json({url:session.url});}
 requireValue(plans[data.plan]&&data.plan!=='free'&&['monthly','yearly'].includes(data.period),400,'Choose a valid plan and billing period.');
 requireValue(!company.stripe_subscription||!['active','trialing','past_due','unpaid','incomplete'].includes(company.subscription_status),409,'Manage your existing subscription in the billing portal.');
 let customer=company.stripe_customer;
 if(!customer){const c=await stripe(env,'customers',{email:user.email,name:company.name,'metadata[company_id]':company.id},'company-'+company.id);customer=c.id;await env.DB.prepare('UPDATE companies SET stripe_customer=? WHERE id=? AND stripe_customer IS NULL').bind(customer,company.id).run();}
 const planKey=data.plan+'_'+data.period;const requestId=crypto.randomUUID();
 const lock=await env.DB.prepare('INSERT INTO checkout_sessions(company_id,request_id,plan_key,expires_at) VALUES(?,?,?,unixepoch()+1800) ON CONFLICT(company_id) DO UPDATE SET request_id=excluded.request_id,session_id=NULL,url=NULL,plan_key=excluded.plan_key,expires_at=excluded.expires_at WHERE checkout_sessions.expires_at<=unixepoch() RETURNING request_id').bind(company.id,requestId,planKey).first();
 if(!lock){const pending=await env.DB.prepare('SELECT * FROM checkout_sessions WHERE company_id=?').bind(company.id).first();requireValue(pending?.url&&pending.plan_key===planKey,409,'A checkout is already open. Complete it or wait for it to expire before selecting a different plan.');return json({url:pending.url});}
 const session=await stripe(env,'checkout/sessions',{mode:'subscription',customer,'client_reference_id':company.id,'line_items[0][price]':priceMap(env)[data.plan+'_'+data.period],'line_items[0][quantity]':'1','subscription_data[metadata][company_id]':company.id,success_url:origin+'/account.html?checkout=success',cancel_url:origin+'/account.html?checkout=cancelled','allow_promotion_codes':'false','expires_at':String(Math.floor(Date.now()/1000)+1800)},'checkout-'+requestId);
 await env.DB.prepare('UPDATE checkout_sessions SET session_id=?,url=?,expires_at=? WHERE company_id=? AND request_id=?').bind(session.id,session.url,session.expires_at,company.id,requestId).run();
 return json({url:session.url});
}
async function webhook(request,env){
 requireValue(env.STRIPE_WEBHOOK_SECRET&&env.STRIPE_SECRET_KEY,503,'Billing webhook is not configured.');const raw=await readText(request,262144);
 requireValue(await verifyStripe(raw,request.headers.get('stripe-signature'),env.STRIPE_WEBHOOK_SECRET),400,'Invalid webhook signature.');
 let event;try{event=JSON.parse(raw);}catch{return json({error:'Invalid event.'},400);}
 requireValue(typeof event.id==='string'&&Number.isInteger(event.created),400,'Invalid billing event.');
 if(await env.DB.prepare('SELECT id FROM webhook_events WHERE id=?').bind(event.id).first())return json({received:true});
 const object=event.data?.object;
 let subscriptionId;if(event.type?.startsWith('customer.subscription.'))subscriptionId=object?.id;
 else if(event.type==='checkout.session.completed')subscriptionId=object?.subscription;
 else return json({received:true,ignored:true});
 requireValue(typeof subscriptionId==='string'&&/^sub_[A-Za-z0-9]+$/.test(subscriptionId),400,'Invalid subscription.');
 // Fetch current provider state: delayed checkout or update events must not restore cancelled access.
 const sub=await stripe(env,'subscriptions/'+subscriptionId);const company=await env.DB.prepare('SELECT * FROM companies WHERE stripe_customer=?').bind(sub.customer).first();
 requireValue(company&&sub.metadata?.company_id===company.id,400,'Subscription does not match a company.');
 // Prevent an old subscription from overwriting a replacement subscription.
 if(company.stripe_subscription&&company.stripe_subscription!==sub.id&&entitled(company))return json({received:true,ignored:true});
 const items=sub.items?.data||[];const price=items[0]?.price?.id;const mapped=Object.entries(priceMap(env)).find(([,v])=>v===price)?.[0];const plan=items.length===1&&items[0].quantity===1&&mapped?mapped.split('_')[0]:'free';
 const end=items[0]?.current_period_end||sub.current_period_end||0;
 await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO webhook_events(id) VALUES(?)').bind(event.id),env.DB.prepare('UPDATE companies SET plan=?,subscription_status=?,stripe_subscription=?,period_end=?,billing_event_created=? WHERE id=? AND billing_event_created<=?').bind(plan,plan==='free'?'inactive':sub.status,sub.id,end,event.created,company.id,event.created)]);
 return json({received:true});
}

// alerts.js
const matchingBids=briefMatches;

async function unsubscribe(request,env){
 const token=new URL(request.url).searchParams.get('token');requireValue(/^[a-f0-9]{64}$/.test(token||''),400,'Invalid unsubscribe link.');const row=await env.DB.prepare('SELECT user_id FROM unsubscribe_tokens WHERE token_hash=? AND expires_at>unixepoch()').bind(await hash(token)).first();requireValue(row,404,'Unsubscribe link expired. Sign in to turn alerts off.');
 if(request.method==='GET')return new Response('<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width"><title>CleanupSignal email preferences</title></head><body><h1>Stop CleanupSignal alerts</h1><p>This stops bid digests and deadline reminders for your account.</p><form method="post"><button>Unsubscribe from all alerts</button></form><p><a href="/account.html">Manage account</a></p></body></html>',{headers:{'content-type':'text/html;charset=utf-8','Cache-Control':'no-store','Referrer-Policy':'no-referrer','Content-Security-Policy':"default-src 'none'; form-action 'self'; frame-ancestors 'none'"}});
 requireValue(request.method==='POST',405,'POST required.');await env.DB.prepare("UPDATE alert_settings SET frequency='off',deadlines=0,updated_at=unixepoch() WHERE user_id=?").bind(row.user_id).run();await env.DB.prepare("UPDATE deliveries SET status='cancelled' WHERE user_id=? AND status IN ('pending','failed')").bind(row.user_id).run();return new Response('You are unsubscribed from CleanupSignal digests and reminders. Your account and billing are unchanged.',{headers:{'content-type':'text/plain','Cache-Control':'no-store'}});
}
async function datasetFor(request,env){const data=await latestDataset(request,env);const age=Date.now()-Date.parse(data.generatedAt);requireValue(Number.isFinite(age)&&age>=-300000&&age<172800000,503,'Bid data is overdue; delivery paused.');return data;}
async function enqueueAlerts(request,env){
 const data=await datasetFor(request,env);const date=new Date().toISOString().slice(0,10);const now=Math.floor(Date.now()/1000);
 const targets=await env.DB.prepare("SELECT m.user_id,m.email,m.company_id,a.frequency,a.deadlines,c.*,p.regions,p.services FROM members m JOIN companies c ON c.id=m.company_id JOIN alert_settings a ON a.user_id=m.user_id LEFT JOIN preferences p ON p.company_id=c.id WHERE a.frequency!='off' OR a.deadlines=1 LIMIT 1001").all();requireValue(targets.results.length<=1000,503,'Delivery batch limit reached. Split customer batches before scaling.');let queued=0;
 for(const target of targets.results){if(!entitled(target))continue;const activeMembers=await env.DB.prepare("SELECT user_id FROM members WHERE company_id=? ORDER BY CASE role WHEN 'owner' THEN 0 ELSE 1 END,created_at,user_id LIMIT ?").bind(target.company_id,({starter:1,team:3,business:8})[target.plan]).all();if(!activeMembers.results.some(m=>m.user_id===target.user_id))continue;
  const prefs={regions:JSON.parse(target.regions||'[]'),services:JSON.parse(target.services||'[]')};const bids=matchingBids(data.signals,prefs);
  const seen=await env.DB.prepare('SELECT fingerprint FROM delivered_items WHERE user_id=?').bind(target.user_id).all();const fingerprints=new Set(seen.results.map(s=>s.fingerprint));
  const recent=await env.DB.prepare("SELECT sent_at FROM deliveries WHERE user_id=? AND kind='digest' AND status='sent' ORDER BY sent_at DESC LIMIT 1").bind(target.user_id).first();
  const kinds=[];
  if(target.frequency==='daily'||target.frequency==='weekly'&&(!recent||now-recent.sent_at>=604800))kinds.push(['digest',bids]);
  if(target.deadlines)kinds.push(['deadline',bids.filter(s=>Date.parse(s.deadline)-Date.now()<=3*86400000)]);
  for(const [kind,records] of kinds){const items=[];for(const s of records){const fingerprint=kind==='deadline'?await hash(s.id+':deadline:'+s.deadline):await hash(s.id+':'+s.title+':'+s.deadline+':'+s.summary+':'+(s.evidenceFingerprint||''));if(!fingerprints.has(fingerprint))items.push({fingerprint,signal:s});}
   if(!items.length)continue;const token=randomToken();const id=await hash(target.user_id+':'+kind+':'+date);const payload={email:target.email,items:items.slice(0,50),datasetAt:data.generatedAt,unsubscribe:new URL('/api/unsubscribe?token='+token,request.url).href};
   const result=await env.DB.batch([env.DB.prepare('INSERT INTO unsubscribe_tokens(token_hash,user_id,expires_at) VALUES(?,?,unixepoch()+31536000)').bind(await hash(token),target.user_id),env.DB.prepare('INSERT OR IGNORE INTO deliveries(id,user_id,kind,payload) VALUES(?,?,?,?)').bind(id,target.user_id,kind,JSON.stringify(payload))]);queued+=result[1].meta.changes;
  }
 }
 return {queued};
}
async function deliverAlerts(env,latest){requireValue(env.RESEND_API_KEY&&env.EMAIL_FROM&&env.RESEND_WEBHOOK_SECRET,503,'Email delivery awaits a verified sender, API key and signed event endpoint.');
 const pending=await env.DB.prepare("SELECT * FROM deliveries WHERE (status IN ('pending','failed') OR (status='sending' AND lease_until<unixepoch())) AND attempts<4 AND created_at>unixepoch()-82800 ORDER BY created_at LIMIT 20").all();let sent=0,failed=0;
 for(const job of pending.results){const claim=await env.DB.prepare("UPDATE deliveries SET status='sending',attempts=attempts+1,lease_until=unixepoch()+600 WHERE id=? AND (status IN ('pending','failed') OR (status='sending' AND lease_until<unixepoch())) RETURNING id").bind(job.id).first();if(!claim)continue;
  try{const target=await env.DB.prepare('SELECT c.*,m.company_id,m.user_id,m.email,a.frequency,a.deadlines,p.regions,p.services FROM members m JOIN companies c ON c.id=m.company_id JOIN alert_settings a ON a.user_id=m.user_id LEFT JOIN preferences p ON p.company_id=c.id WHERE m.user_id=?').bind(job.user_id).first();
   const payload=JSON.parse(job.payload);const suppressed=await env.DB.prepare('SELECT email_hash FROM email_suppressions WHERE email_hash=?').bind(await hash(String(payload.email).trim().toLowerCase())).first();if(suppressed||target&&target.email.toLowerCase()!==String(payload.email).toLowerCase()||!target||!entitled(target)||(job.kind==='digest'?target.frequency==='off':!target.deadlines)){await env.DB.prepare("UPDATE deliveries SET status='cancelled' WHERE id=?").bind(job.id).run();continue;}
   // Recheck the dataset immediately before delivery. Do not email withdrawn/expired notices.
   const membersNow=await env.DB.prepare("SELECT user_id FROM members WHERE company_id=? ORDER BY CASE role WHEN 'owner' THEN 0 ELSE 1 END,created_at,user_id LIMIT ?").bind(target.company_id,({starter:1,team:3,business:8})[target.plan]).all();if(!membersNow.results.some(m=>m.user_id===job.user_id)){await env.DB.prepare("UPDATE deliveries SET status='cancelled' WHERE id=?").bind(job.id).run();continue;}
   const delivered=await env.DB.prepare('SELECT fingerprint FROM delivered_items WHERE user_id=?').bind(job.user_id).all();const seenNow=new Set(delivered.results.map(x=>x.fingerprint));
   const current=new Map(matchingBids(latest.signals,{regions:JSON.parse(target.regions||'[]'),services:JSON.parse(target.services||'[]')}).map(s=>[s.id,s]));const valid=payload.items.filter(i=>{const s=current.get(i.signal.id);return !seenNow.has(i.fingerprint)&&s&&s.deadline===i.signal.deadline&&s.title===i.signal.title&&s.summary===i.signal.summary&&s.evidenceFingerprint===i.signal.evidenceFingerprint;});if(!valid.length){await env.DB.prepare("UPDATE deliveries SET status='cancelled' WHERE id=?").bind(job.id).run();continue;}
   const {html,text}=renderBriefing({signals:valid.map(i=>current.get(i.signal.id)),datasetAt:latest.generatedAt||payload.datasetAt,workspaceUrl:new URL('/account.html',payload.unsubscribe).href,unsubscribeUrl:payload.unsubscribe});
   const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':job.id},body:JSON.stringify({from:env.EMAIL_FROM,to:[payload.email],subject:job.kind==='deadline'?'CleanupSignal: bid deadlines within 3 days':'CleanupSignal: your matched open bids',text,html,headers:{'List-Unsubscribe':'<'+payload.unsubscribe+'>','List-Unsubscribe-Post':'List-Unsubscribe=One-Click'}}),signal:AbortSignal.timeout(15000)});
   if(!response.ok){await response.body?.cancel();throw new Error('Email provider rejected delivery.');}const result=await response.json();
   await env.DB.batch([env.DB.prepare("UPDATE deliveries SET status='sent',provider_id=?,sent_at=unixepoch(),last_error=NULL WHERE id=?").bind(result.id,job.id),...valid.map(i=>env.DB.prepare('INSERT OR IGNORE INTO delivered_items(user_id,fingerprint) VALUES(?,?)').bind(job.user_id,i.fingerprint))]);sent++;
  }catch{await env.DB.prepare("UPDATE deliveries SET status='failed',last_error='Email delivery failed; retry scheduled' WHERE id=?").bind(job.id).run();failed++;}
 }
 return {sent,failed};
}
async function automation(request,env){
 const supplied=request.headers.get('authorization')?.replace(/^Bearer /,'');requireValue(env.AUTOMATION_TOKEN&&await constantEqual(supplied,env.AUTOMATION_TOKEN),401,'Unauthorized automation request.');
 const id=crypto.randomUUID();try{const queued=await enqueueAlerts(request,env);const delivery=await deliverAlerts(env,await datasetFor(request,env));await env.DB.prepare('INSERT INTO job_runs(id,kind,status,detail) VALUES(?,?,?,?)').bind(id,'alerts',delivery.failed?'degraded':'success',JSON.stringify({...queued,...delivery})).run();
  await env.DB.batch([env.DB.prepare('DELETE FROM rate_limits WHERE window<?').bind(Math.floor(Date.now()/60000)-60),env.DB.prepare('DELETE FROM unsubscribe_tokens WHERE expires_at<unixepoch()'),env.DB.prepare("UPDATE deliveries SET status='failed',last_error='Retry window expired; operator review required' WHERE status IN ('pending','sending') AND created_at<=unixepoch()-82800")]);return json({...queued,...delivery});
 }catch(e){await env.DB.prepare('INSERT INTO job_runs(id,kind,status,detail) VALUES(?,?,?,?)').bind(id,'alerts','failed','Delivery paused. Review provider configuration and source freshness.').run();throw e;}
}
async function deliveryStatus(request,env){const {user,company}=await workspaceFor(request,env);const rows=await env.DB.prepare('SELECT kind,status,attempts,created_at,sent_at,last_error FROM deliveries WHERE user_id=? ORDER BY created_at DESC LIMIT 20').bind(user.id).all();return json({deliveries:rows.results,company:company.name});}

// support.js
const categories=['Incorrect project or deadline','Source outage or missing coverage','Website problem or accessibility','Privacy, correction or deletion request','General question'];
async function submitSupport(request,env){
 requireValue(env.SUPPORT_ENABLED==='true'&&env.SUPPORT_SALT,503,'Online support is not configured. Please use the email or download option.');
 const body=await bodyJson(request);
 requireValue(!body.website,400,'Request rejected.');
 const email=String(body.email||'').trim().toLowerCase(),message=String(body.message||'').trim(),reference=String(body.record||'').trim();
 requireValue(categories.includes(body.type)&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)&&email.length<=254&&message.length>=10&&message.length<=4000&&reference.length<=500,400,'Provide a valid contact email, request type and a description of 10–4,000 characters.');
 const ip=request.headers.get('CF-Connecting-IP');requireValue(ip,503,'Please use the email option while online support is unavailable.');
 const window=Math.floor(Date.now()/3600000),key='support:'+await hash(env.SUPPORT_SALT+':'+window+':'+ip);
 // Conditional upsert reserves capacity atomically, including concurrent requests.
 const quota=await env.DB.prepare('INSERT INTO rate_limits(key,window,count) VALUES(?,?,1) ON CONFLICT(key) DO UPDATE SET count=count+1 WHERE count<5 RETURNING count').bind(key,window*60).first();
 requireValue(quota,429,'Too many requests. Please wait an hour or email support.');
 const id='CS-'+crypto.randomUUID();
 const inserted=await env.DB.prepare("INSERT INTO support_requests(id,category,email,record_reference,message) SELECT ?,?,?,?,? WHERE (SELECT count(*) FROM support_requests WHERE created_at>unixepoch()-86400)<200 RETURNING id").bind(id,body.type,email,reference,message).first();
 requireValue(inserted,503,'Online support is at capacity. Please email support instead.');
 return json({id,message:'Your request has been saved for operator review. Keep this reference. No confirmation email has been sent.'},201);
}

// email-events.js
async function verifyEmailSignature(raw,headers,secret,now=Math.floor(Date.now()/1000)){
 try{
  const id=headers.get('svix-id')||'',stamp=headers.get('svix-timestamp')||'',signatures=headers.get('svix-signature')||'';
  if(!secret?.startsWith('whsec_')||!id||id.length>200||!/^\d+$/.test(stamp)||Math.abs(now-Number(stamp))>300)return false;
  const key=await crypto.subtle.importKey('raw',Uint8Array.from(atob(secret.slice(6)),c=>c.charCodeAt(0)),{name:'HMAC',hash:'SHA-256'},false,['verify']);
  for(const sig of signatures.split(' ').slice(0,10))if(sig.startsWith('v1,')&&await crypto.subtle.verify('HMAC',key,Uint8Array.from(atob(sig.slice(3)),c=>c.charCodeAt(0)),new TextEncoder().encode(id+'.'+stamp+'.'+raw)))return true;
 }catch{}
 return false;
}
async function emailWebhook(request,env){
 requireValue(env.RESEND_WEBHOOK_SECRET,503,'Email event verification is not configured.');
 const raw=await readText(request,65536);requireValue(await verifyEmailSignature(raw,request.headers,env.RESEND_WEBHOOK_SECRET),400,'Invalid email event signature.');
 let event;try{event=JSON.parse(raw);}catch{requireValue(false,400,'Invalid event.');}
 const accepted=['email.delivered','email.bounced','email.complained','email.delivery_delayed','email.failed'];
 if(!accepted.includes(event.type))return json({received:true,ignored:true});
 const id=request.headers.get('svix-id');if(await env.DB.prepare('SELECT id FROM email_events WHERE id=?').bind(id).first())return json({received:true,duplicate:true});
 requireValue(typeof event.data?.email_id==='string'&&event.data.email_id.length<=200,400,'Missing email reference.');
 const job=await env.DB.prepare('SELECT id,user_id,payload FROM deliveries WHERE provider_id=?').bind(event.data.email_id).first();
 // Let the provider retry an event that raced ahead of the delivery acknowledgement.
 requireValue(job,503,'Delivery acknowledgement pending.');
 const statements=[env.DB.prepare('INSERT OR IGNORE INTO email_events(id,delivery_id,event_type) VALUES(?,?,?)').bind(id,job.id,event.type)];
 if(['email.bounced','email.complained'].includes(event.type)){
  const email=String(JSON.parse(job.payload).email).trim().toLowerCase();
  statements.push(env.DB.prepare('INSERT OR IGNORE INTO email_suppressions(email_hash,reason) VALUES(?,?)').bind(await hash(email),event.type));
  statements.push(env.DB.prepare("UPDATE alert_settings SET frequency='off',deadlines=0,updated_at=unixepoch() WHERE user_id=? AND EXISTS(SELECT 1 FROM members WHERE user_id=? AND lower(email)=?)").bind(job.user_id,job.user_id,email));
  statements.push(env.DB.prepare("UPDATE deliveries SET status='cancelled' WHERE user_id=? AND status IN ('pending','failed')").bind(job.user_id));
 }
 await env.DB.batch(statements);return json({received:true});
}

// worker.js
export default {async fetch(request,env){
 const path=new URL(request.url).pathname;
 if(!path.startsWith('/api/'))return env.ASSETS.fetch(request);
 try{
  if(path==='/api/signals.json'&&request.method==='GET')return await publicSignals(request,env);
  if(path==='/api/config'&&request.method==='GET')return json({accounts:Boolean(env.DB)&&authReady(env),billing:billingReady(env),email:Boolean(env.RESEND_API_KEY&&env.EMAIL_FROM&&env.RESEND_WEBHOOK_SECRET),support:env.SUPPORT_ENABLED==='true',passwordless:true});
  if(!env.DB)return json({error:'Company workspace setup is pending. Public research remains available.'},503);
  if(path==='/api/email/webhook'&&request.method==='POST')return await emailWebhook(request,env);
  if(path==='/api/billing/webhook'&&request.method==='POST')return await webhook(request,env);
  if(path==='/api/jobs/alerts'&&request.method==='POST')return await automation(request,env);
  if(path==='/api/unsubscribe')return await unsubscribe(request,env);
  if(!['GET','POST','PUT','DELETE'].includes(request.method))return json({error:'Method not allowed.'},405);
  if(request.method!=='GET')checkOrigin(request);
  if(path==='/api/support'&&request.method==='POST')return await submitSupport(request,env);
  if(path.startsWith('/api/auth/')&&request.method==='POST')return await authRoute(request,env,path.split('/').pop());
  if(['/api/billing/checkout','/api/billing/portal'].includes(path)&&request.method==='POST')return await billingRoute(request,env,path);
  if(path==='/api/deliveries'&&request.method==='GET')return await deliveryStatus(request,env);
  if(['/api/workspace','/api/preferences','/api/watchlist','/api/invitations','/api/invitations/accept','/api/members','/api/alerts'].includes(path))return await workspaceRoute(request,env,path);
  return json({error:'API route not found.'},404);
 }catch(error){
  if(error instanceof HttpError)return json({error:error.message},error.status);
  if(/seat_limit/.test(error.message))return json({error:'Your plan has no available seats. Remove a pending invitation or member, or upgrade your plan.'},409);
  if(/UNIQUE constraint/.test(error.message))return json({error:'This account or invitation already exists.'},409);
  console.error(JSON.stringify({event:'api_failure',path}));return json({error:'This action could not be completed. Please retry later.'},503);
 }
}};
